def param(cle, defaut=""):
    r = Parametres.lookupOne(Cle=cle)
    return r.Valeur if r and r.Valeur else defaut

appli = param("Nom_application", "Cette application")
mail = param("Contact_support", "applications@outre-mer.gouv.fr")
return (
  "# ⛔ Pour avoir accès aux données, rapprochez-vous des administrateurs 👮\n\n"
  "**%s** n'est accessible qu'aux utilisateurs dont l'adresse mail a été enregistrée par la **DGOM**, un **AdminTerritoire** ou un **AdminRPROG**.\n\n"
  "En cas de difficulté, contactez vos correspondants en charge des contrats ou la DGOM à l'adresse [%s](mailto:%s)."
) % (appli, mail, mail)
